}
*{box-sizing:border-box;}
body{
  margin:0;
  background:var(--cream);
  color:var(--ink);
  font-family:'Hind Siliguri','Noto Sans Bengali',sans-serif;
  min-height:100vh;
}
h1,h2,h3,.brand{
  font-family:'Noto Serif Bengali',serif;
}

/* ---------- Header ---------- */
.topbar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:14px 24px;
  background:var(--green-deep);
  color:var(--cream);
