def print_tree(nodes, items, path, depth):
    for n in nodes:
        p = path + [n["name"]]
        print("   " + "    " * depth + f"├─ {n['name']}  ({count_code_items(items, p)})")
        print_tree(n["children"], items, p, depth + 1)


