      "content": "# MJ-Registry\n\nV1.0 \n\n`index.html`\n```\n<!DOCTYPE html>\n<html lang=\"bn\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>MJ Ahmad — Registry</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#F3F5F2;--pan:#FFFFFF;--ink:#16211E;--mut:#5F6E69;--line:#D9DFDB;--pine:#0F4C42;--brass:#B8862B;--ok:#2E7D4F;--warn:#B8862B;--bad:#B3412E;--sel:#E3EEEA;--r:6px}\n@media(prefers-color-scheme:dark){:root{--bg:#0F1514;--pan:#161E1C;--ink:#E6ECE9;--mut:#93A29C;--line:#26332F;--pine:#5FB59F;--brass:#D4A74A;--ok:#5DB985;--warn:#D4A74A;--bad:#E1705B;--sel:#1E2D29}}\n*{box-sizing:border-box;margin:0}\nhtml,body{height:100%}\nbody{font-family:\"Hind Siliguri\",\"Noto Sans Bengali\",system-ui,sans-serif;background:var(--bg);color:var(--ink);display:flex;flex-direction:column;font-size:15px;line-height:1.5}\n:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n#splash{position:fixed;inset:0;z-index:99;background:var(--pine);color:#F3F5F2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;cursor:pointer;transition:opacity .5s}\n#splash.out{opacity:0;pointer-events:none}\n#splash img{width:96px;height:96px;object-fit:contain}\n#splash h1{font-size:34px;font-weight:700;letter-spacing:.5px}\n#splash p{opacity:.8}\n#splash i{display:block;height:2px;width:0;background:var(--brass);animation:bar var(--ms,1.8s) linear forwards}\n@keyframes bar{to{width:180px}}\nheader{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--pine);color:#F3F5F2;flex:none}\nheader img{width:36px;height:36px;object-fit:contain}\nheader h1{font-size:18px;font-weight:700;line-height:1.2}\nheader small{display:block;opacity:.8;font-size:12px}\n#q{margin-left:auto;width:min(320px,45%);padding:7px 10px;border-radius:var(--r);border:1px solid #ffffff44;background:#ffffff1c;color:#fff;font:inherit}\n#q::placeholder{color:#ffffffaa}\n#burger{display:none;background:none;border:0;color:#fff;font-size:22px}\n.main{flex:1;display:flex;min-height:0}\nnav{width:290px;flex:none;overflow:auto;background:var(--pan);border-right:1px solid var(--line);padding:10px 6px}\nnav ul{list-style:none;padding:0}\nnav ul ul{margin-left:14px;border-left:1px solid var(--line);padding-left:4px}\n.node{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:var(--r);cursor:pointer;user-select:none}\n.node:hover{background:var(--sel)}\n.node.act{background:var(--sel);color:var(--pine);font-weight:600;box-shadow:inset 3px 0 var(--brass)}\n.chev{width:16px;text-align:center;color:var(--mut);transition:transform .15s;flex:none}\n.open>.node .chev{transform:rotate(90deg)}\nnav li>ul{display:none}nav li.open>ul{display:block}\n.ic{width:18px;text-align:center;flex:none}\n.lb{flex:1;min-width:0}.lb small{display:block;color:var(--mut);font-size:11.5px;line-height:1.2;font-weight:400}\n.cnt{font-size:11.5px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:0 7px;color:var(--mut)}\nsection#view{flex:1;overflow:auto;padding:20px 24px}\nh2{font-size:22px;margin-bottom:2px}.sub{color:var(--mut);margin-bottom:14px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:22px}\n.stat{background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:12px;cursor:pointer}\n.stat b{font-size:28px;display:block;line-height:1.1}.stat span{color:var(--mut);font-size:13px}\n.stat.bad b{color:var(--bad)}\n.bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}\n.chip{border:1px solid var(--line);background:var(--pan);color:var(--ink);border-radius:16px;padding:2px 12px;font:inherit;font-size:13px;cursor:pointer}\n.chip.on{background:var(--pine);color:#fff;border-color:var(--pine)}\n.row{display:grid;grid-template-columns:132px 1fr auto;gap:12px;align-items:center;background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:9px 12px;margin-bottom:6px;cursor:pointer}\n.row:hover{border-color:var(--pine)}\n.id{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine)}\n.tt small{display:block;color:var(--mut);font-size:12.5px}\n.b{display:inline-block;font-size:12px;border-radius:4px;padding:0 7px;border:1px solid var(--line);margin-left:4px;white-space:nowrap}\n.b.todo,.b.low,.b.pass{color:var(--ok)}.b.doing,.b.medium,.b.warning{color:var(--warn)}.b.high,.b.urgent,.b.fail{color:var(--bad)}.b.done{color:var(--mut)}\n.empty{padding:40px 0;color:var(--mut);text-align:center}\n#modal{position:fixed;inset:0;background:#0008;display:none;z-index:50;justify-content:flex-end}\n#modal.on{display:flex}\n#modal .p{width:min(520px,100%);background:var(--pan);height:100%;overflow:auto;padding:22px}\n#modal dl{display:grid;grid-template-columns:110px 1fr;gap:6px 10px;margin:14px 0}\n#modal dt{color:var(--mut)}#modal dd{margin:0;word-break:break-word}\n#modal .lnk{color:var(--pine);cursor:pointer;text-decoration:underline;font-family:ui-monospace,monospace;font-size:13px;margin-right:8px}\n.hist{border-left:2px solid var(--line);padding-left:12px;margin-top:8px;font-size:13px;color:var(--mut)}\n.hist div{margin-bottom:6px}\n.x{float:right;background:none;border:0;font-size:22px;color:var(--mut);cursor:pointer}\nfooter{flex:none;padding:8px 16px;background:var(--pan);border-top:1px solid var(--line);color:var(--mut);font-size:12.5px;display:flex;flex-wrap:wrap;gap:6px 18px;justify-content:space-between}\n@media(max-width:820px){#burger{display:block}nav{position:fixed;top:56px;bottom:0;left:0;z-index:40;transform:translateX(-100%);transition:transform .2s;width:290px}nav.on{transform:none}.row{grid-template-columns:1fr}section#view{padding:14px}}\n.lang{display:flex;border:1px solid #ffffff55;border-radius:var(--r);overflow:hidden;flex:none}\n.lang button{background:none;border:0;color:#fff;padding:5px 11px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;opacity:.75}\n.lang button+button{border-left:1px solid #ffffff55}\n.lang button.on{background:var(--brass);opacity:1}\n#splash .tg{font-style:italic;max-width:420px;text-align:center;font-size:13px;opacity:.65;padding:0 20px}\nfooter{gap:8px;flex-direction:column;align-items:stretch;max-height:45vh;overflow:auto}\nfooter a{color:var(--pine);text-decoration:none;font-weight:500}footer a:hover{text-decoration:underline}\n.fl{display:flex;flex-wrap:wrap;gap:6px 20px}\nfooter summary{cursor:pointer;color:var(--ink);font-weight:500}\n.cm{display:grid;grid-template-columns:200px 1fr;gap:4px 12px;padding:4px 0;border-bottom:1px dashed var(--line)}\n.cm code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine);cursor:pointer;word-break:break-all}\n.fq{font-style:italic;color:var(--ink)}\n@media(max-width:820px){.cm{grid-template-columns:1fr}#q{width:34%}}\n.lg{background:var(--lc,#6B7B76);color:#fff;font-size:12px;font-weight:700;border-radius:4px;padding:1px 8px;letter-spacing:.4px;white-space:nowrap;align-self:flex-start}\n.row .lg{margin-left:4px}\n.l-html{--lc:#D8552B}.l-json{--lc:#A38F1A}.l-python{--lc:#3776AB}.l-node{--lc:#3F8A36}.l-shell{--lc:#3E8E3E}.l-css{--lc:#2965F1}.l-ts{--lc:#3178C6}.l-react{--lc:#1F8EA8}.l-markdown{--lc:#5B6B8C}.l-sql{--lc:#8A5AA8}\n.cc{background:var(--pan);border:1px solid var(--line);border-left:4px solid var(--lc,#6B7B76);border-radius:var(--r);margin-bottom:14px;overflow:hidden}\n.cch{display:flex;gap:12px;align-items:flex-start;padding:10px 12px}\n.ct{flex:1;min-width:0}.ct small{display:block;color:var(--mut)}\n.ca{display:flex;gap:6px}\n.ca button,.tg2{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:var(--r);padding:3px 12px;font:inherit;font-size:13px;cursor:pointer}\n.ca button:hover,.tg2:hover{border-color:var(--pine);color:var(--pine)}\n.tg2{margin:8px 12px 10px}\n.cb{display:flex;background:#0F1917;color:#D8E4DF;font:12.5px/1.6 ui-monospace,Menlo,Consolas,monospace;overflow:auto;position:relative;max-height:70vh}\n.cb pre{margin:0}.cb .gt{padding:10px 10px 10px 12px;color:#5F7A72;text-align:right;user-select:none;border-right:1px solid #ffffff14;position:sticky;left:0;background:#0F1917}\n.cb .cd{padding:10px 14px;flex:1;min-width:0;tab-size:2}\n.cc.fade .cb{cursor:pointer;overflow:hidden}.cc.fade .cb::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:30px;background:linear-gradient(transparent,#0F1917)}\n@media(prefers-reduced-motion:reduce){*{transition:none!important;animation-duration:.01s!important}}\n</style>\n</head>\n<body>\n<div id=\"splash\"><img id=\"sl\" alt=\"Logo\"><h1 id=\"st\">MJ Ahmad</h1><p id=\"ss\"></p><p id=\"sq\" class=\"tg\"></p><i></i></div>\n<header>\n  <button id=\"burger\" aria-label=\"Menu\">☰</button>\n  <img id=\"hl\" alt=\"Logo\">\n  <div><h1 id=\"ht\">MJ Ahmad</h1><small id=\"hs\"></small></div>\n  <input id=\"q\" type=\"search\" placeholder=\"খুঁজুন / Search — ID, শিরোনাম, ট্যাগ…\" aria-label=\"Search\">\n  <div class=\"lang\" id=\"lang\" role=\"group\" aria-label=\"Language\"><button data-l=\"en\">EN</button><button data-l=\"bn\">BN</button></div>\n</header>\n<div class=\"main\"><nav id=\"nav\" aria-label=\"Menu\"></nav><section id=\"view\"></section></div>\n<footer><div class=\"fl\" id=\"fl\"></div><details id=\"fd\"><summary id=\"fs\"></summary><div id=\"fc\"></div></details><div class=\"fq\" id=\"fq\"></div><div class=\"fm\" id=\"f2\"></div></footer>\n<div id=\"modal\"><div class=\"p\" id=\"mp\"></div></div>\n<script>\nconst $=s=>document.querySelector(s),E=(t,c,h)=>{const e=document.createElement(t);if(c)e.className=c;if(h!=null)e.innerHTML=h;return e};\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst UI={\nen:{search:'Search — ID, title, tag…',dash:'Dashboard',recent:'Recent',searchT:'Search',all:'All',empty:'Nothing here yet. Add entrie