y:block;color:var(--mut);font-size:11.5px;line-height:1.2;font-weight:400}\n.cnt{font-size:11.5px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:0 7px;color:var(--mut)}\nsection#view{flex:1;overflow:auto;padding:20px 24px}\nh2{font-size:22px;margin-bottom:2px}.sub{color:var(--mut);margin-bottom:14px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:22px}\n.stat{background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:12px;cursor:pointer}\n.stat b{font-size:28px;display:block;line-height:1.1}.stat span{color:var(--mut);font-size:13px}\n.stat.bad b{color:var(--bad)}\n.bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}\n.chip{border:1px solid var(--line);background:var(--pan);color:var(--ink);border-radius:16px;padding:2px 12px;font:inherit;font-size:13px;cursor:pointer}\n.chip.on{background:var(--pine);color:#fff;border-color:var(--pine)}\n.row{display:grid;grid-template-columns:132px 1fr auto;gap:12px;align-items:center;background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:9px 12px;margin-bottom:6px;cursor:pointer}\n.row:hover{border-color:var(--pine)}\n.id{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine)}\n.tt small{display:block;color:var(--mut);font-size:12.5px}\n.b{display:inline-block;font-size:12px;border-radius:4px;padding:0 7px;border:1px solid var(--line);margin-left:4px;white-space:nowrap}\n.b.todo,.b.low,.b.pass{color:var(--ok)}.b.doing,.b.medium,.b.warning{color:var(--warn)}.b.high,.b.urgent,.b.fail{color:var(--bad)}.b.done{color:var(--mut)}\n.empty{padding:40px 0;color:var(--mut);text-align:center}\n#modal{position:fixed;inset:0;background:#0008;display:none;z-index:50;justify-content:flex-end}\n#modal.on{display:flex}\n#modal .p{width:min(520px,100%);background:var(--pan);height:100%;overflow:auto;padding:22px}\n#modal dl{display:grid;grid-template-columns:110px 1fr;gap:6px 10px;margin:14px 0}\n#modal dt{color:var(--mut)}#modal dd{margin:0;word-break:break-word}\n#modal .lnk{color:var(--pine);cursor:pointer;text-decoration:underline;font-family:ui-monospace,monospace;font-size:13px;margin-right:8px}\n.hist{border-left:2px solid var(--line);padding-left:12px;margin-top:8px;font-size:13px;color:var(--mut)}\n.hist div{margin-bottom:6px}\n.x{float:right;background:none;border:0;font-size:22px;color:var(--mut);cursor:pointer}\nfooter{flex:none;padding:8px 16px;background:var(--pan);border-top:1px solid var(--line);color:var(--mut);font-size:12.5px;display:flex;flex-wrap:wrap;gap:6px 18px;justify-content:space-between}\n@media(max-width:820px){#burger{display:block}nav{position:fixed;top:56px;bottom:0;left:0;z-index:40;transform:translateX(-100%);transition:transform .2s;width:290px}nav.on{transform:none}.row{grid-template-columns:1fr}section#view{padding:14px}}\n.lang{display:flex;border:1px solid #ffffff55;border-radius:var(--r);overflow:hidden;flex:none}\n.lang button{background:none;border:0;color:#fff;padding:5px 11px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;opacity:.75}\n.lang button+button{border-left:1px solid #ffffff55}\n.lang button.on{background:var(--brass);opacity:1}\n#splash .tg{font-style:italic;max-width:420px;text-align:center;font-size:13px;opacity:.65;padding:0 20px}\nfooter{gap:8px;flex-direction:column;align-items:stretch;max-height:45vh;overflow:auto}\nfooter a{color:var(--pine);text-decoration:none;font-weight:500}footer a:hover{text-decoration:underline}\n.fl{display:flex;flex-wrap:wrap;gap:6px 20px}\nfooter summary{cursor:pointer;color:var(--ink);font-weight:500}\n.cm{display:grid;grid-template-columns:200px 1fr;gap:4px 12px;padding:4px 0;border-bottom:1px dashed var(--line)}\n.cm code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine);cursor:pointer;word-break:break-all}\n.fq{font-style:italic;color:var(--ink)}\n@media(max-width:820px){.cm{grid-template-columns:1fr}#