aScript-এর সিনট্যাক্স ও `validate.py` যাচাই করেছি, কিন্তু ব্রাউজারে খুলে দেখিনি। `assets/logo.png` আমার এখানে নেই, তাই লোগো আপনার লোকালে দেখে নিন।\n\n1. **লোগো:** \"M\" ফ্যালব্যাক পুরোপুরি বাদ। হেডার ও স্প্ল্যাশ দুই জায়গায় সরাসরি `meta.logo` (`assets/logo.png`) লিংক থেকে লোগো লোড হয়।\n2. **EN | BN টগল:** হেডারে বোতাম যোগ হয়েছে, ডিফল্ট EN। BN বেছে নিলে মেনু, ড্যাশবোর্ড, স্ট্যাটাস, ফিল্টার, বিস্তারিত প্যানেল, ফুটার, তারিখ ও শিরোনাম (`title_bn` থাকলে) বাংলায় দেখায়। পছন্দ মনে থাকে, পরের বার খুললে একই ভাষা থাকবে।\n3. **ফুটার:** সেখানে আপনার চলমান প্রজেক্ট, ওয়েবসাইট, ইমেইল ও লিংকডিনের লিংক আছে। এর নিচে \"Quick commands & emergency help\" ভাঁজ করা অংশে সব শেল কমান্ড আছে। কমান্ডে ক্লিক করলে কপি হয়। জরুরি অবস্থায় `data.json.bak` থেকে ফেরত আনার কমান্ডও আছে।\n4. **ট্যাগলাইন:** আপনার লাইনটি স্প্ল্যাশ স্ক্রিন ও ফুটারে বসিয়েছি।\n\nফুটারের লিংক, কমান্ড ও ট্যাগলাইন সবই `data.json`-এর `meta.links`, `meta.commands` ও `meta.tagline` থেকে আসে। ভবিষ্যতে এগুলো বদলাতে শুধু `data.json` এডিট করলেই হবে, `index.html` ছুঁতে হবে না।\n\n---\n\n## V1.2\n\n`add_task.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_task.py \"Title\" [--bn \"শিরোনাম\"] [--desc ..] [--priority low|medium|high|urgent] [--due YYYY-MM-DD] [--category ..] [--tags a,b]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--desc\", default=\"\")\na.add_argument(\"--priority\", default=\"medium\", choices=[\"low\", \"medium\", \"high\", \"urgent\"])\na.add_argument(\"--due\", default=\"\"); a.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New task (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\"); x.desc = ask(\"Description\")\n    x.priority = ask(\"Priority low/medium/high/urgent\", \"medium\", choices=[\"low\", \"medium\", \"high\", \"urgent\"])\n    x.due = ask(\"Due YYYY-MM-DD\"); x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\")\nd = load(); i = next_id(d, \"task\")\nd[\"tasks\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"desc\": x.desc, \"status\": \"todo\",\n  \"priority\": x.priority, \"due\": x.due, \"category\": x.category, \"tags\": tags(x.tags),\n  \"created_at\": now(), \"completed_at\": \"\", \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Task added:\", i)\n```\n\n---\n\n`add_note.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_note.py \"Title\" [--bn ..] [--body ..] [--category ..] [--tags a,b] [--pinned]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--body\", default=\"\")\na.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\"); a.add_argument(\"--pinned\", action=\"store_true\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New note (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\"); x.body = ask(\"Body\")\n    x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\"); x.pinned = ask(\"Pin? y/n\", \"n\", choices=[\"y\", \"n\"]) == \"y\"\nd = load(); i = next_id(d, \"note\")\nd[\"notes\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"body\": x.body, \"category\": x.category,\n  \"tags\": tags(x.tags), \"pinned\": x.pinned, \"created_at\": now(), \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Note added:\", i)\n```\n\n---\n\n`add_audit.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_audit.py \"Title\" --result pass|warning|fail [--target ..] [--findings ..] [--auditor ..] [--related TSK-2026-0001,NOT-..] [--bn ..] [--category ..] [--tags ..]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--result\", default=\"\", choices=[\"pass\", \"warning\", \"fail\"])\na.add_argument(\"--target\", default=\"\"); a.add_argument(\"--findings\", default=\"\"); a.add_argument(\"--auditor\", default=\"\")\na.add_argument(\"--related\", default=\"\"); a.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New audit (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\")\n    x.result = ask(\"Result pass/warning/fail *\", req=True, choices=[\"pass\", \"warning\", \"fail\"])\n    x.target = ask(\"Target\"); x.findings = ask(\"Findings\"); x.auditor = ask(\"Auditor\", \"MJ Ahmad\")\n    x.related = ask(\"Related IDs a,b\"); x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\")\nif not x.result: die(\"--result is required (pass|warning|fail)\")\nd = load()\nfor r in tags(x.related):\n    if find(d, r)[0] is None: die(f\"related ID not found: {r}\")\ni = next_id(d, \"audit\")\nd[\"audits\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"result\": x.result, \"target\": x.target,\n  \"findings\": x.findings, \"auditor\": x.auditor, \"related\": tags(x.related), \"category\": x.category,\n  \"tags\": tags(x.tags), \"created_at\": now(), \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Audit added:\", i)\n```\n\n---\n\n`complete_task.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 complete_task.py TSK-2026-0001 [--note \"...\"] [--status doing|done|todo]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser(); a.add_argument(\"id\", nargs=\"?\", default=\"\"); a.add_argument(\"--note\", default=\"\")\na.add_argument(\"--status\", default=\"done\", choices=[\"todo\", \"doing\", \"done\"])\nx = a.parse_args(); d = load()\nif not x.id:\n    for t in d[\"tasks\"]:\n        if t[\"status\"] != \"done\": print(f'  {t[\"id\"]}  [{t[\"status\"]}]  {t[\"title\"]}')\n    x.id = ask(\"Task ID *\", req=True); x.note = ask(\"Note\"); k, t = find(d, x.id)\nif k != \"task\": die(f\"task not found: {x.id}\")\nt[\"status\"] = x.status; t[\"completed_at\"] = now() if x.status == \"done\" else \"\"\nt[\"history\"].append({\"at\": now(), \"event\": \"status → \" + x.status, \"note\": x.note})\nsave(d); print(f\"✔ {x.id} → {x.status}\")\n```\n\n---\n\n`_lib.py`\n```\n#!/usr/bin/env python3\n\"\"\"Shared helpers: load/save data.json safely, unique IDs, history log.\"\"\"\nimport json, os, shutil, sys\nfrom datetime import datetime\nHERE = os.path.dirname(os.path.abspath(__file__))\nDATA = os.path.join(HERE, \"data.json\")\nKIND = {\"task\": (\"TSK\", \"tasks\"), \"note\": (\"NOT\", \"notes\"), \"audit\": (\"AUD\", \"audits\"), \"code\": (\"CDE\", \"codes\")}\n\ndef now(): return datetime.now().astimezone().isoformat(timespec=\"seconds\")\n\ndef load():\n    with open(DATA, encoding=\"utf-8\") as f: d = json.load(f)\n    d.setdefault(\"codes\", []); return d\n\ndef save(d):\n    d[\"meta\"][\"updated_at\"] = now()\n    if os.path.exists(DATA): shutil.copy(DATA, DATA + \".bak\")\n    tmp = DATA + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(d, f, ensure_ascii=False, indent=2)\n    os.replace(tmp, DATA)\n\ndef next_id(d, kind):\n    \"\"\"Never reuses an ID: PREFIX-YYYY-NNNN, counter kept per kind & year.\"\"\"\n    p, _ = KIND[kind]; y = datetime.now().year\n    c = d[\"meta\"].setdefault(\"counters\", {}).setdefault(kind, {})\n    c[str(y)] = c.get(str(y), 0) + 1\n    return f\"{p}-{y}-{c[str(y)]:04d}\"\n\ndef find(d, id_):\n    for k, (p, key) in KIND.items():\n        for it in d[key]:\n            if it[\"id\"] == id_: return k, it\n    return None, None\n\ndef tags(s): return [t.strip() for t in (s or \"\").split(\",\") if t.strip()]\n\ndef die(msg): print(\"ERROR:\", msg, file=sys.stderr); sys.exit(1)\n\ndef ask(label, default=\"\", req=False, choices=None):\n    \"\"\"Interactive prompt used when a script runs without arguments.\"\"\"\n    while True:\n        v = input(f\"{label}{' ['+default+']' if default else ''}: \").strip() or default\n        if req and not v: print(\"  required\"); continue\n        if choices and v not in choices: print(\"  choose:\", \"/\".join(choices)); continue\n        return v\n\nimport hashlib\nEXT = {\"html\":(\"html\",\"HTML\"),\"htm\":(\"html\",\"HTML\"),\"json\":(\"json\",\"JSON\"),\"py\":(\"python\",\"Python\"),\n \"js\":(\"node\",\"Node.js\"),\"mjs\":(\"node\",\"Node.js\"),\"cjs\":(\"node\",\"Node.js\"),\"ts\":(\"ts\",\"TypeScript\"),\n \"jsx\":(\"react\",\"React\"),\"tsx\":(\"react\",\"React\"),\"sh\":(\"shell\",\"Shell\"),\"bash\":(\"shell\",\"Shell\"),\n \"css\":(\"css\",\"CSS\"),\"md\":(\"markdown\",\"Markdown\"),\"yml\":(\"yaml\",\"YAML\"),\"yaml\":(\"yaml\",\"YAML\"),\n \"sql\":(\"sql\",\"SQL\"),\"xml\":(\"xml\",\"XML\"),\"php\":(\"php\",\"PHP\"),\"java\":(\"java\",\"Java\"),\"c\":(\"c\",\"C\"),\n \"cpp\":(\"cpp\",\"C++\"),\"go\":(\"go\",\"Go\"),\"rs\":(\"rust\",\"Rust\"),\"txt\":(\"text\",\"Text\")}\nSHEBANG = {\"python\":(\"python\",\"Python\"),\"node\":(\"node\",\"Node.js\"),\"bash\":(\"shell\",\"Shell\"),\"sh\":(\"shell\",\"Shell\")}\n\ndef detect(name, text, force=\"\"):\n    if force:\n        return next((v for v in EXT.values() if v[0] == force), (force, force.upper()))\n    ext = name.rsplit(\".\", 1)[-1].lower() if \".\" in name else \"\"\n    if ext in EXT: return EXT[ext]\n    if text.startswith(\"#!\"):\n        for k, v in SHEBANG.items():\n            if k in text.split(\"\\n\", 1)[0]: return v\n    return (\"text\", \"Text\")\n\nimport re\ndef walk(ns, path=()):\n    for n in ns:\n        yield n, path + (n[\"id\"],)\n        yield from walk(n.get(\"children\", []), path + (n[\"id\"],))\n\ndef find_node(d, ref):\n    \"\"\"ref = menu id, or a label path like 'CodeCraft/Web/Portal' (EN/BN/id, case-insensitive). -> (node, [id path]) or (None, None)\"\"\"\n    ref = ref.strip()\n    for n, p in walk(d[\"menu\"]):\n        if n[\"id\"] == ref: return n, list(p)\n    segs = [s.strip().lower() for s in ref.strip(\"/\").split(\"/\") if s.strip()]\n    if not segs: return None, None\n    def go(ns, sg, path):\n        for n in ns:\n            if sg[0] in (n[\"id\"].lower(), (n.get(\"en\") or \"\").lower(), (n.get(\"bn\") or \"\").lower()):\n                if len(sg) == 1: return n, path + [n[\"id\"]]\n                r = go(n.get(\"children\", []), sg[1:], path + [n[\"id\"]])\n                if r[0]: return r\n        return None, None\n    r = go(d[\"menu\"], segs, [])\n    if r[0]: return r\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)   # 'Web/Portal' means CodeCraft/Web/Portal\n    return go(root.get(\"children\", []), segs, [\"codecraft\"]) if root else (None, None)\n\ndef ensure_root(d):\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)\n    if not root:\n        root = {\"id\": \"codecraft\", \"bn\": \"কোডক্রাফ্ট\", \"en\": \"CodeCraft\", \"icon\": \"❮❯\", \"open\": True, \"view\": {\"type\": \"codes\"}, \"children\": []}\n        k = next((j for j, n in enumerate(d[\"menu\"]) if n[\"id\"] == \"registry\"), len(d[\"menu\"])); d[\"menu\"].insert(k, root)\n    root.setdefault(\"children\", []); return root\n\ndef ensure_chain(d, parent, ppath, names, bns=()):\n    \"\"\"Create (or reuse, matched by name) nested submenus under parent. -> (deepest node, id path)\"\"\"\n    ids = {n[\"id\"] for n, _ in walk(d[\"menu\"])}\n    for k, name in enumerate(names):\n        sib = parent.setdefault(\"children\", [])\n        hit = next((c for c in sib if name.lower() in ((c.get(\"en\") or \"\").lower(), (c.get(\"bn\") or \"\").lower())), None)\n        if not hit:\n            bn = bns[k].strip() if k < len(bns) and bns[k].strip() else name\n            base = \"c-\" + (re.sub(r\"[^a-z0-9]+\", \"-\", name.lower()).strip(\"-\") or \"m\"); nid = base; i = 2\n            while nid in ids: nid = f\"{base}-{i}\"; i += 1\n            ids.add(nid)\n            hit = {\"id\": nid, \"bn\": bn, \"en\": name, \"view\": {\"type\": \"codes\", \"filter\": {\"menu_path\": nid}}}\n            sib.append(hit)\n        parent = hit; ppath = ppath + [hit[\"id\"]]\n    return parent, ppath\n\ndef normalize(d):\n    \"\"\"Upgrade older data: language nodes filter by menu_path; entries get a menu_path.\"\"\"\n    root = ensure_root(d)\n    for c in root[\"children\"]:\n        f = c.get(\"view\", {}).get(\"filter\", {})\n        if \"lang\" in f: c[\"view\"][\"filter\"] = {\"menu_path\": c[\"id\"]}\n    for it in d[\"codes\"]:\n        it.setdefault(\"menu_path\", [\"codecraft\", \"c-\" + it[\"lang\"]])\n    return d\n```\n\n---\n\nএটা কোনো ত্রুটি নয়। আমার ডিজাইনে `title` বাধ্যতামূলক আর্গুমেন্ট ছিল, আর আপনি কোনো শিরোনাম না দিয়ে চালিয়েছেন। তবে আপনি প্রশ্নোত্তর ধরনের ইন্টারঅ্যাকটিভ মোড আশা করেছিলেন বলে মনে হচ্ছে, তাই সেটা যোগ করে দিয়েছি।\n\nএখন আর্গুমেন্ট ছাড়া চালালে একটি একটি করে জিজ্ঞেস করবে। ঐচ্ছিক ঘরে শুধু Enter চাপলেই হয়:\n\n```\n./add_task.py        # শিরোনাম (EN/BN), বিবরণ, অগ্রাধিকার, শেষ তারিখ, বিভাগ, ট্যাগ\n./add_note.py        # শিরোনাম, বিবরণ, বিভাগ, ট্যাগ, পিন\n./add_audit.py       # শিরোনাম, ফলাফল, লক্ষ্য, পর্যবেক্ষণ, অডিটর, সম্পর্কিত আইডি\n./complete_task.py   # খোলা টাস্কের তালিকা দেখিয়ে আইডি চাইবে\n```\n\nএকবারে দিতে চাইলে আগের মতোই চলবে:\n\n```\n./add_task.py \"Fix login\" --bn \"লগইন ঠিক করা\" --priority high --due 2026-10-05\n```\n\nআপডেট হয়েছে `_lib.py`, `add_task.py`, `add_note.py`, `add_audit.py` ও `complete_task.py`। এই পাঁচটি ফাইল আপনার ফোল্ডারে রিপ্লেস করুন, `data.json` ছোঁয়ার দরকার নেই। প্রতিটি রান শেষে `./run.sh check` চালিয়ে ডাটা যাচাই করে নিতে পারেন।\n\n---\n\n## V1.3\n\n*CodeCraft*\n\n`index.html`\n```\n<!DOCTYPE html>\n<html lang=\"bn\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>MJ Ahmad — Registry</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#F3F5F2;--pan:#FFFFFF;--ink:#16211E;--mut:#5F6E69;--line:#D9DFDB;--pine:#0F4C42;--brass:#B8862B;--ok:#2E7D4F;--warn:#B8862B;--bad:#B3412E;--sel:#E3EEEA;--r:6px}\n@media(prefers-color-scheme:dark){:root{--bg:#0F1514;--pan:#161E1C;--ink:#E6ECE9;--mut:#93A29C;--line:#26332F;--pine:#5FB59F;--brass:#D4A74A;--ok:#5DB985;--warn:#D4A74A;--bad:#E1705B;--sel:#1E2D29}}\n*{box-sizing:border-box;margin:0}\nhtml,body{height:100%}\nbody{font-family:\"Hind Siliguri\",\"Noto Sans Bengali\",system-ui,sans-serif;background:var(--bg);color:var(--ink);display:flex;flex-direction:column;font-size:15px;line-height:1.5}\n:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n#splash{position:fixed;inset:0;z-index:99;background:var(--pine);color:#F3F5F2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;cursor:pointer;transition:opacity .5s}\n#splash.out{opacity:0;pointer-events:none}\n#splash img{width:96px;height:96px;object-fit:contain}\n#splash h1{font-size:34px;font-weight:700;letter-spacing:.5px}\n#splash p{opacity:.8}\n#splash i{display:block;height:2px;width:0;background:var(--brass);animation:bar var(--ms,1.8s) linear forwards}\n@keyframes bar{to{width:180px}}\nheader{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--pine);color:#F3F5F2;flex:none}\nheader img{width:36px;height:36px;object-fit:contain}\nheader h1{font-size:18px;font-weight:700;line-height:1.2}\nheader small{display:block;opacity:.8;font-size:12px}\n#q{margin-left:auto;width:min(320px,45%);padding:7px 10px;border-radius:var(--r);border:1px solid #ffffff44;background:#ffffff1c;color:#fff;font:inherit}\n#q::placeholder{color:#ffffffaa}\n#burger{display:none;background:none;border:0;color:#fff;font-size:22px}\n.main{flex:1;display:flex;min-he