m _lib import *\nMAX = 2 * 1024 * 1024\na = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\na.add_argument(\"source\", nargs=\"?\", default=\"\"); a.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"desc\", nargs=\"?\", default=\"\")\na.add_argument(\"--bn\", action=\"append\", default=[]); a.add_argument(\"--title-bn\", default=\"\"); a.add_argument(\"--desc-bn\", default=\"\")\na.add_argument(\"--menu\", default=\"\"); a.add_argument(\"--new-menu\", default=\"\"); a.add_argument(\"--new-menu-bn\", default=\"\")\na.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\"); a.add_argument(\"--lang\", default=\"\"); a.add_argument(\"--force\", action=\"store_true\")\nx = a.parse_intermixed_args()\nif not x.source:\n    print(\"— New CodeCraft entry (Enter to skip optional fields) —\")\n    x.source = ask(\"File path or URL *\", req=True); x.title = ask(\"Title (EN)\"); x.title_bn = ask(\"শিরোনাম (BN)\")\n    x.desc = ask(\"Description (EN)\"); x.desc_bn = ask(\"বর্ণনা (BN)\")\n    x.menu = ask(\"Existing menu (id or path, Enter = by file type; ./run.sh menu shows the tree)\")\n    x.new_menu = ask(\"New submenu name(s) e.g. UI/Forms (optional)\"); x.new_menu_bn = ask(\"নতুন সাবমেনুর বাংলা নাম (optional)\") if x.new_menu else \"\"\n    x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\")\ntb = x.title_bn or (x.bn[0] if x.bn else \"\"); db = x.desc_bn or (x.bn[1] if len(x.bn) > 1 else \"\")\nsrc = x.source\ntry:\n    if src.startswith((\"http://\", \"https://\")):\n        with urllib.request.urlopen(urllib.request.Request(src, headers={\"User-Agent\": \"mj-registry\"}), timeout=20) as r: raw = r.read(MAX + 1)\n        name = os.path.basename(urlparse(src).path) or \"index.html\"\n    else:\n        p = os.path.abspath(os.path.expanduser(src))\n        if not os.path.isfile(p): die(f\"file not found: {src}\")\n        with open(p, \"rb\") as f: raw = f.read(MAX + 1)\n        name = os.path.basename(p)\nexcept Exception as e: die(f\"could not read {src}: {e}\")\nif len(raw) > MAX: die(\"file larger than 2 MB\")\ntry: text = raw.decode(\"utf-8-sig\").replace(\"\\r\\n\", \"\\n\")\nexcept UnicodeDecodeError: die(\"not a UTF-8 text file (binary files are not supported)\")\nlang, label = detect(name, text, x.lang.lower())\nsha = hashlib.sha256(text.encode(\"utf-8\")).hexdigest()\nd = normalize(load()); root = ensure_root(d)\ndup = next((c for c in d[\"codes\"] if c.get(\"sha256\") == sha), None)\nif dup and not x.force: die(f\"identical content already saved as {dup['id']} (use --force to add anyway)\")\nnode, path = root, [\"codecraft\"]\nif x.menu:\n    node, path = find_node(d, x.menu)\n    if not node: die(f\"menu not found: {x.menu}  (run ./run.sh menu to see the tree, or create it with --new-menu)\")\nif x.new_menu:\n    node, path = ensure_chain(d, node, path, [s.strip() for s in x.new_menu.split(\"/\") if s.strip()], x.new_menu_bn.split(\"/\"))\nelif not x.menu:\n    node, path = ensure_chain(d, root, [\"codecraft\"], [label])\ni = next_id(d, \"code\")\nd[\"codes\"].append({\"id\": i, \"title\": x.title or name, \"title_bn\": tb, \"desc\": x.desc, \"desc_bn\": db, \"filename\": name,\n  \"source\": src, \"lang\": lang, \"lang_label\": label, \"ext\": name.rsplit(\".\", 1)[-1].lower() if \".\" in name else \"\",\n  \"lines\": text.count(\"\\n\") + (0 if text == \"\" or text.endswith(\"\\n\") else 1), \"bytes\": len(raw), \"sha256\": sha,\n  \"menu_path\": path, \"category\": x.category, \"tags\": tags(x.tags), \"created_at\": now(),\n  \"history\": [{\"at\": now(), \"event\": \"created\", \"note\": src}], \"content\": text})\nsave(d); print(f\"✔ CodeCraft added: {i}  [{label}]  {name}  →  \" + \" › \".join(next(n for n, p in walk(d['menu']) if n['id'] == k)['en'] for k in path))\n```\n\n---\n\n`_lib.py`\n```\n#!/usr/bin/env python3\n\"\"\"Shared helpers: load/save data.json safely, unique IDs, history log.\"\"\"\nimport json, os, shutil, sys\nfrom datetime import datetime\nHERE = os.path.dirname(os.path.abspath(__file__))\nDATA = os.path.join(HERE, \"data.json\")\nKIND = {\"task\": (\"TSK\", \"tasks\"), \"note\": (\"NOT\", \"notes\"), \"audit\": (\"AUD\", \"audits\"), \"code\": (\"CDE\", \"codes\")}\n\ndef now(): return datetime.now().astimezone().isoformat(timespec=\"seconds\")\n\ndef load():\n    with open(DATA, encoding=\"utf-8\") as f: d = json.load(f)\n    d.setdefault(\"codes\", []); return d\n\ndef save(d):\n    d[\"meta\"][\"updated_at\"] = now()\n    if os.path.exists(DATA): shutil.copy(DATA, DATA + \".bak\")\n    tmp = DATA + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(d, f, ensure_ascii=False, indent=2)\n    os.replace(tmp, DATA)\n\ndef next_id(d, kind):\n    \"\"\"Never reuses an ID: PREFIX-YYYY-NNNN, counter kept per kind & year.\"\"\"\n    p, _ = KIND[kind]; y = datetime.now().year\n    c = d[\"meta\"].setdefault(\"counters\", {}).setdefault(kind, {})\n    c[str(y)] = c.get(str(y), 0) + 1\n    return f\"{p}-{y}-{c[str(y)]:04d}\"\n\ndef find(d, id_):\n    for k, (p, key) in KIND.items():\n        for it in d[key]:\n            if it[\"id\"] == id_: return k, it\n    return None, None\n\ndef tags(s): return [t.strip() for t in (s or \"\").split(\",\") if t.strip()]\n\ndef die(msg): print(\"ERROR:\", msg, file=sys.stderr); sys.exit(1)\n\ndef ask(label, default=\"\", req=False, choices=None):\n    \"\"\"Interactive prompt used when a script runs without arguments.\"\"\"\n    while True:\n        v = input(f\"{label}{' ['+default+']' if default else ''}: \").strip() or default\n        if req and not v: print(\"  required\"); continue\n        if choices and v not in choices: print(\"  choose:\", \"/\".join(choices)); continue\n        return v\n\nimport hashlib\nEXT = {\"html\":(\"html\",\"HTML\"),\"htm\":(\"html\",\"HTML\"),\"json\":(\"json\",\"JSON\"),\"py\":(\"python\",\"Python\"),\n \"js\":(\"node\",\"Node.js\"),\"mjs\":(\"node\",\"Node.js\"),\"cjs\":(\"node\",\"Node.js\"),\"ts\":(\"ts\",\"TypeScript\"),\n \"jsx\":(\"react\",\"React\"),\"tsx\":(\"react\",\"React\"),\"sh\":(\"shell\",\"Shell\"),\"bash\":(\"shell\",\"Shell\"),\n \"css\":(\"css\",\"CSS\"),\"md\":(\"markdown\",\"Markdown\"),\"yml\":(\"yaml\",\"YAML\"),\"yaml\":(\"yaml\",\"YAML\"),\n \"sql\":(\"sql\",\"SQL\"),\"xml\":(\"xml\",\"XML\"),\"php\":(\"php\",\"PHP\"),\"java\":(\"java\",\"Java\"),\"c\":(\"c\",\"C\"),\n \"cpp\":(\"cpp\",\"C++\"),\"go\":(\"go\",\"Go\"),\"rs\":(\"rust\",\"Rust\"),\"txt\":(\"text\",\"Text\")}\nSHEBANG = {\"python\":(\"python\",\"Python\"),\"node\":(\"node\",\"Node.js\"),\"bash\":(\"shell\",\"Shell\"),\"sh\":(\"shell\",\"Shell\")}\n\ndef detect(name, text, force=\"\"):\n    if force:\n        return next((v for v in EXT.values() if v[0] == force), (force, force.upper()))\n    ext = name.rsplit(\".\", 1)[-1].lower() if \".\" in name else \"\"\n    if ext in EXT: return EXT[ext]\n    if text.startswith(\"#!\"):\n        for k, v in SHEBANG.items():\n            if k in text.split(\"\\n\", 1)[0]: return v\n    return (\"text\", \"Text\")\n\nimport re\ndef walk(ns, path=()):\n    for n in ns:\n        yield n, path + (n[\"id\"],)\n        yield from walk(n.get(\"children\", []), path + (n[\"id\"],))\n\ndef find_node(d, ref):\n    \"\"\"ref = menu id, or a label path like 'CodeCraft/Web/Portal' (EN/BN/id, case-insensitive). -> (node, [id path]) or (None, None)\"\"\"\n    ref = ref.strip()\n    for n, p in walk(d[\"menu\"]):\n        if n[\"id\"] == ref: return n, list(p)\n    segs = [s.strip().lower() for s in ref.strip(\"/\").split(\"/\") if s.strip()]\n    if not segs: return None, None\n    def go(ns, sg, path):\n        for n in ns:\n            if sg[0] in (n[\"id\"].lower(), (n.get(\"en\") or \"\").lower(), (n.get(\"bn\") or \"\").lower()):\n                if len(sg) == 1: return n, path + [n[\"id\"]]\n                r = go(n.get(\"children\", []), sg[1:], path + [n[\"id\"]])\n                if r[0]: return r\n        return None, None\n    r = go(d[\"menu\"], segs, [])\n    if r[0]: return r\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)   # 'Web/Portal' means CodeCraft/Web/Portal\n    return go(root.get(\"children\", []), segs, [\"codecraft\"]) if root else (None, None)\n\ndef ensure_root(d):\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)\n    if not root:\n        root = {\"id\": \"codecraft\", \"bn\": \"কোডক্রাফ্ট\", \"en\": \"CodeCraft\", \"icon\": \"❮❯\", \"open\": True, \"view\": {\"type\": \"codes\"}, \"children\": []}\n        k = next((j for j, n in enumerate(d[\"menu\"]) if n[\"id\"] == \"registry\"), len(d[\"menu\"])); d[\"menu\"].insert(k, root)\n    root.setdefault(\"children\", []); return root\n\ndef ensure_chain(d, parent, ppath, names, bns=()):\n    \"\"\"Create (or reuse, matched by name) nested submenus under parent. -> (deepest node, id path)\"\"\"\n    ids = {n[\"id\"] for n, _ in walk(d[\"menu\"])}\n    for k, name in enumerate(names):\n        sib = parent.setdefault(\"children\", [])\n        hit = next((c for c in sib if name.lower() in ((c.get(\"en\") or \"\").lower(), (c.get(\"bn\") or \"\").lower())), None)\n        if not hit:\n            bn = bns[k].strip() if k < len(bns) and bns[k].strip() else name\n            base = \"c-\" + (re.sub(r\"[^a-z0-9]+\", \"-\", name.lower()).strip(\"-\") or \"m\"); nid = base; i = 2\n            while nid in ids: nid = f\"{base}-{i}\"; i += 1\n            ids.add(nid)\n            hit = {\"id\": nid, \"bn\": bn, \"en\": name, \"view\": {\"type\": \"codes\", \"filter\": {\"menu_path\": nid}}}\n            sib.append(hit)\n        parent = hit; ppath = ppath + [hit[\"id\"]]\n    return parent, ppath\n\ndef normalize(d):\n    \"\"\"Upgrade older data: language nodes filter by menu_path; entries get a menu_path.\"\"\"\n    root = ensure_root(d)\n    for c in root[\"children\"]:\n        f = c.get(\"view\", {}).get(\"filter\", {})