ted_at\": \"2026-09-24T09:10:00+06:00\",\n      \"completed_at\": \"\",\n      \"history\": [\n        {\n          \"at\": \"2026-09-24T09:10:00+06:00\",\n          \"event\": \"created\"\n        }\n      ]\n    }\n  ],\n  \"notes\": [\n    {\n      \"id\": \"NOT-2026-0001\",\n      \"title\": \"How this system works\",\n      \"title_bn\": \"এই সিস্টেম যেভাবে কাজ করে\",\n      \"body\": \"index.html never changes. Add data with the scripts; the page reads data.json.\",\n      \"category\": \"guide\",\n      \"tags\": [\n        \"guide\"\n      ],\n      \"pinned\": true,\n      \"created_at\": \"2026-09-24T09:15:00+06:00\",\n      \"history\": [\n        {\n          \"at\": \"2026-09-24T09:15:00+06:00\",\n          \"event\": \"created\"\n        }\n      ]\n    },\n    {\n      \"id\": \"NOT-2026-0002\",\n      \"title\": \"ID format\",\n      \"title_bn\": \"আইডি ফরম্যাট\",\n      \"body\": \"TSK / NOT / AUD + year + serial. IDs are never reused.\",\n      \"category\": \"guide\",\n      \"tags\": [\n        \"id\"\n      ],\n      \"pinned\": false,\n      \"created_at\": \"2026-09-24T09:20:00+06:00\",\n      \"history\": [\n        {\n          \"at\": \"2026-09-24T09:20:00+06:00\",\n          \"event\": \"created\"\n        }\n      ]\n    }\n  ],\n  \"audits\": [\n    {\n      \"id\": \"AUD-2026-0001\",\n      \"title\": \"Data integrity check\",\n      \"title_bn\": \"ডাটা ইন্টিগ্রিটি যাচাই\",\n      \"result\": \"pass\",\n      \"target\": \"data.json\",\n      \"findings\": \"No duplicate IDs.\",\n      \"auditor\": \"MJ Ahmad\",\n      \"related\": [\n        \"TSK-2026-0001\"\n      ],\n      \"category\": \"system\",\n      \"tags\": [\n        \"integrity\"\n      ],\n      \"created_at\": \"2026-09-24T10:10:00+06:00\",\n      \"history\": [\n        {\n          \"at\": \"2026-09-24T10:10:00+06:00\",\n          \"event\": \"created\"\n        }\n      ]\n    },\n    {\n      \"id\": \"AUD-2026-0002\",\n      \"title\": \"Logo file present\",\n      \"title_bn\": \"লোগো ফাইল আছে কিনা\",\n      \"result\": \"warning\",\n      \"target\": \"assets/logo.png\",\n      \"findings\": \"Logo not yet added.\",\n      \"auditor\": \"MJ Ahmad\",\n      \"related\": [\n        \"TSK-2026-0002\"\n      ],\n      \"category\": \"system\",\n      \"tags\": [\n        \"logo\"\n      ],\n      \"created_at\": \"2026-09-24T10:12:00+06:00\",\n      \"history\": [\n        {\n          \"at\": \"2026-09-24T10:12:00+06:00\",\n          \"event\": \"created\"\n        }\n      ]\n    }\n  ],\n  \"codes\": []\n}\n```\n\n---\n\nCodeCraft যুক্ত করেছি। স্ক্রিপ্টগুলো একটি কপিতে আপনার উদাহরণের মতো করে চালিয়ে পরীক্ষা করেছি, আইডি, মেনু ও validate ঠিক কাজ করেছে। CodeCraft-এর কার্ড আর মেনু ব্রাউজারে খুলে দেখিনি, শুধু JavaScript-এর সিনট্যাক্স যাচাই করেছি।\n\n**ব্যবহার**\n```\n./run.sh code ~/mj/portal/index.html \"Title\" \"Description\" --bn \"শিরোনাম\" --bn \"বর্ণনা\"\n./add_code.py https://example.com/app.py \"API script\"     # লিংক থেকেও চলে\n./add_code.py                                              # আর্গুমেন্ট ছাড়া = প্রশ্নোত্তর মোড\n```\nপ্রথম `--bn` শিরোনামের বাংলা, দ্বিতীয় `--bn` বর্ণনার বাংলা। চাইলে `--title-bn` ও `--desc-bn` আলাদা করেও দেওয়া যায়। শিরোনাম না দিলে ফাইলের নামই শিরোনাম হয়।\n\n**কী ঘটে**\n- পুরো ফাইলের কনটেন্ট `data.json`-এর `codes`-এ যায় এবং আইডি হয় `CDE-2026-0001` ধরনের।\n- ফাইলের ধরন এক্সটেনশন বা shebang দেখে চেনা হয় (HTML, JSON, Python, Node.js, Shell, CSS, TypeScript, SQL ইত্যাদি)। ভুল ধরা পড়লে `--lang python` দিয়ে ঠিক করা যায়।\n- CodeCraft মেনুর নিচে ওই ধরনের সাব-মেনু নিজে থেকে তৈরি হয়, যেমন CodeCraft → HTML।\n- একই কনটেন্ট দ্বিতীয়বার দিলে আটকে দেয়, `--force` দিলে যুক্ত হয়। ২ MB-র বড় বা বাইনারি ফাইল নেয় না।\n\n**দেখতে যেমন**\n- কার্ডের এক পাশে ধরনের রঙিন ব্যাজ, অন্য পাশে **Copy** (পুরো কোড কপি হয়) ও ডাউনলোড বোতাম।\n- কোড ডার্ক প্যানেলে লাইন নম্বরসহ শুরুতে ৪ লাইন দেখায়। ওই সংখ্যা `data.json`-এর `meta.code_preview_lines` থেকে বদলানো যায়।\n- **Show all** বা কোডের অংশে ক্লিক করলে পুরোটা খোলে, **Collapse** চাপলে আগের অবস্থায় ফেরে।\n- ড্যাশবোর্ড, সার্চ ও রেজিস্ট্রিতেও CodeCraft আসে। EN|BN টগল এখানেও কাজ করে।\n\n`index.html`-এ CodeCraft দেখানোর জন্য শেষবারের মতো একটি বদল করা হয়েছে। এরপর নতুন ধরনের ফাইল যোগ করলেও এটি বদলাতে হবে না। আপডেট হয়েছে `index.html`, `add_code.py` (নতুন), `_lib.py`, `validate.py`, `run.sh` ও `data.json`। আপনার `data.json`-এ নিজের এন্ট্রি থাকলে রিপ্লেস না করে তিনটি জিনিস হাতে যোগ করুন: `\"codes\": []`, মেনুতে `codecraft` নোড, আর `meta.counters`-এ `\"code\": {}`।\n\n---\n\n\n"
    }
